def play(commands):
    room = "hall"
    inventory = []
    message = describe(room)
    for command in commands:
        parts = command.split(" ", 1)
        if len(parts) == 2 and parts[0] == "go":
            room, message = move(room, parts[1])
        elif len(parts) == 2 and parts[0] == "take":
