def fetch(url, server):
    hops = []
    while True:
        if url in hops:
            return 0, "redirect loop", hops
        hops.append(url)
        if url not in server:
            return 404, "", hops
        status, headers, body = parse_response(server[url])
        if status in (301, 302, 307, 308) and "location" in headers:
            url = headers["location"]
        else:
            return status, body, hops

def fetch_many(urls, server):
    cache = {}
    results = []
    misses = 0
    for url in urls:
        if url in cache:
            results.append(cache[url])
            continue
        misses += 1
        status, body, _hops = fetch(url, server)
        if status == 200:
            cache[url] = (status, body)
        results.append((status, body))
    return results, misses

