import java.util.*;

class Solution {
    // Money is stored in cents (a long), so it never has rounding errors.
    static String money(long cents) {
        return String.format("$%d.%02d", cents / 100, cents % 100);
    }

    static class Account {
        private final String id;
        private final String owner;
        private long balance;   // in cents

        Account(String id, String owner, long balance) {
            if (balance < 0) throw new IllegalArgumentException("opening balance cannot be negative");
            this.id = id;
            this.owner = owner;
            this.balance = balance;
        }

        String getId() {
            return id;
        }

        String getOwner() {
            return owner;
        }

        long getBalance() {
            return balance;
        }

        @Override
        public String toString() {
            return id + " (" + owner + "): " + money(balance);
        }

        Account deposit(long amount) {
            if (amount <= 0) throw new IllegalArgumentException("amount must be positive");
            balance += amount;
            return this;   // returning this lets calls chain
        }

        Account withdraw(long amount) {
            if (amount <= 0) throw new IllegalArgumentException("amount must be positive");
            if (amount > balance) throw new IllegalStateException("insufficient funds");
            balance -= amount;
            return this;
        }
    }

    static class Bank {
        private final List<Account> accounts = new ArrayList<>();
        private final List<String> log = new ArrayList<>();

        Bank open(String id, String owner, long balance) {
            for (Account a : accounts) {
                if (a.getId().equals(id)) throw new IllegalArgumentException("duplicate id: " + id);
            }
            accounts.add(new Account(id, owner, balance));
            return this;
        }

        Account find(String id) {
            for (Account a : accounts) {
                if (a.getId().equals(id)) return a;
            }
            throw new NoSuchElementException("no account: " + id);
        }

        Bank transfer(String fromId, String toId, long amount) {
            try {
                Account from = find(fromId);
                Account to = find(toId);   // look both up before any money moves
                from.withdraw(amount);
                to.deposit(amount);
                log.add("ok: " + fromId + " -> " + toId + " " + money(amount));
            } catch (RuntimeException e) {
                log.add("failed: " + e.getMessage());
            }
            return this;
        }

        List<String> getLog() {
            return log;
        }

        Bank addInterest(double ratePercent) {
            if (ratePercent < 0) throw new IllegalArgumentException("rate cannot be negative");
            for (Account a : accounts) {
                long interest = Math.round(a.getBalance() * ratePercent / 100);
                if (interest > 0) a.deposit(interest);
            }
            return this;
        }

        List<String> report() {
            List<Account> sorted = new ArrayList<>(accounts);   // a copy, so the bank's order stays the same
            sorted.sort(Comparator.comparingLong(Account::getBalance).reversed().thenComparing(Account::getId));
            List<String> lines = new ArrayList<>();
            long total = 0;
            for (Account a : sorted) {
                lines.add(a.toString());
                total += a.getBalance();
            }
            lines.add("Total: " + money(total));
            return lines;
        }
    }

    static Bank sample() {
        return new Bank().open("A1", "Ana", 5000).open("B2", "Ben", 1000);
    }
}

