def shortest_path(graph, start, goal):
    best = {start: 0}
    previous = {}
    heap = [(0, start)]
    while heap:
        dist, town = heapq.heappop(heap)
        if town == goal:
            route = [town]
            while route[-1] != start:
                route.append(previous[route[-1]])
            return dist, route[::-1]
